const input = $input.first().json || {};
const payload = input.payload || {};
const correlationId = input.correlation_id || $execution.id;
const userId = input.user_id;
const taskIds = payload.task_ids || input.task_ids || (input.task_id ? [input.task_id] : []);
const additional = payload.additional_reminders || input.additional_reminders || [];

if (!userId) throw new Error('WF-REM-001: user_id is required');
if (!Array.isArray(taskIds) || taskIds.length === 0) {
  return [{json:{ok:true,status:'no_op',correlation_id:correlationId,data:{reason:'no_task_ids'},warnings:[]}}];
}
if (!Array.isArray(additional)) throw new Error('WF-REM-001: additional_reminders must be an array');

return taskIds.map((taskId) => {
  const proposals = additional
    .filter((r) => !r.task_id || String(r.task_id) === String(taskId))
    .map((r) => ({
      kind: r.kind || 'ai',
      planned_at: r.planned_at,
      reason: r.reason || null
      // can_break_silence is deliberately NOT accepted from model/user proposal.
    }));
  return {json:{
    correlation_id:correlationId,
    user_id:userId,
    task_id:taskId,
    additional_reminders_json:JSON.stringify(proposals)
  }};
});

const rows = $input.all().map((item) => {
  const raw = item.json.res;
  return typeof raw === 'string' ? JSON.parse(raw) : raw;
});
const reqs = $('Validate and Expand Planning Request').all();
const correlationId = reqs[0]?.json?.correlation_id || $execution.id;
return [{json:{
  ok:true,status:'completed',correlation_id:correlationId,
  data:{
    task_count:rows.length,
    planning_results:rows,
    created_count:rows.reduce((n,r)=>n+Number(r?.created_count||0),0),
    existing_count:rows.reduce((n,r)=>n+Number(r?.existing_count||0),0)
  },
  warnings:[]
}}];
